# Spans the rule may delete: document numbers, dates/years, names (person, place). Order matters: longest first.
DELETABLE = [
    r" số \d+/\d{4}/[\wĐđ\-]+", r" số \d+/[\wĐđ\-]+", r" ngày \d{1,2}/\d{1,2}/\d{4}", r"Từ ngày \d{1,2}/\d{1,2}/\d{4}, ",
    r"Từ đầu năm \d{4}, ", r",? (vào |từ )?năm \d{4}", r" \d{4}(?=[:,. )])", r" tại phường Thượng Cát", r" cầu Thượng Cát", r" phường Thượng Cát",
]


def _norm(s: str) -> str:
    for p in DELETABLE:
        s = re.sub(p, "", s)
    return re.sub(r"\s+", " ", s).strip().lower()


def check() -> None:
    """cau_hoi must be whole sentences of nguyen_van after deleting only DELETABLE spans."""
    assert len(MOC) == 30 and len({m[0] for m in MOC}) == 30 and len({m[3] for m in MOC}) == 30
    for mid, _, day, _, raw, q in MOC:
        assert day < "2026-11-22", mid
        src = _norm(raw)
        for sent in re.split(r"(?<=[.?!])\s+(?=[A-ZÀ-ỸĐ\"“])", q):
            s = _norm(sent)
            assert s in src, (mid, sent)
        assert not re.search(r"\d+/\d{4}/|\d{1,2}/\d{1,2}/\d{4}|năm (19|20)\d{2}|Thượng Cát|B\.T\.T", q), mid


if __name__ == "__main__":
    check()
    print("moc_src: 30 câu, luật rút gọn đạt")
